keyframes.ms-fade-word-in:
@keyframes ms-fade-word-in { 
  0% { opacity: 0; filter: blur(5px); transform: translateY(10px); }
  100% { opacity: 1; filter: blur(); transform: none; }
}

keyframes.ms-showcase-word:
@keyframes ms-showcase-word { 
  0% { opacity: 0; transform: translateY(40%); }
  2%, 7.3% { opacity: 1; transform: none; }
  9%, 100% { opacity: 0; transform: translateY(-40%); }
}

keyframes.ms-showcase-straighten:
@keyframes ms-showcase-straighten { 
  0% { opacity: 0.5; transform: translateY(70px) rotate(var(--ms-showcase-tilt,0deg)) scale(.9); }
}

keyframes.ms-hx-srIn:
@keyframes ms-hx-srIn { 
  0% { opacity: 0; transform: translateY(12px) scale(0.97); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-hx-kwRow:
@keyframes ms-hx-kwRow { 
  100% { background: color-mix(in srgb, var(--color-warning) 16%, var(--color-white)); box-shadow: color-mix(in srgb, var(--color-warning) 16%, var(--color-white)) 0px 0px 0px 6px; }
}

keyframes.ms-hx-phDrift:
@keyframes ms-hx-phDrift { 
  0% { transform: translate(0px, 0px); }
  28% { transform: translate(0.6px, -2.6px); }
  52% { transform: translate(0.2px, -4px); }
  77% { transform: translate(-0.5px, -1.8px); }
  100% { transform: translate(0px, 0px); }
}

keyframes.ms-hx-cardDriftA:
@keyframes ms-hx-cardDriftA { 
  0% { transform: translate(0px, 0px) rotate(0deg); }
  30% { transform: translate(2.5px, -4px) rotate(0.35deg); }
  60% { transform: translate(4px, -6px) rotate(0.2deg); }
  82% { transform: translate(1.5px, -2.5px) rotate(-0.15deg); }
  100% { transform: translate(0px, 0px) rotate(0deg); }
}

keyframes.ms-hx-cardDriftB:
@keyframes ms-hx-cardDriftB { 
  0% { transform: translate(0px, 0px) rotate(0deg); }
  25% { transform: translate(-2px, -3px) rotate(-0.3deg); }
  55% { transform: translate(-4.5px, -5.5px) rotate(-0.45deg); }
  80% { transform: translate(-1.5px, -2px) rotate(-0.1deg); }
  100% { transform: translate(0px, 0px) rotate(0deg); }
}

keyframes.ms-hx-capInA:
@keyframes ms-hx-capInA { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-hx-capOutA:
@keyframes ms-hx-capOutA { 
  0% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(-10px); }
}

keyframes.ms-hx-bldIn:
@keyframes ms-hx-bldIn { 
  0% { opacity: 0.3; transform: translateY(10px); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-hx-capInB:
@keyframes ms-hx-capInB { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-hx-capOutB:
@keyframes ms-hx-capOutB { 
  0% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(-10px); }
}

keyframes.ms-hx-barGrow2:
@keyframes ms-hx-barGrow2 { 
  0% { transform-origin: 0px center; transform: scaleX(0); }
  100% { transform-origin: 0px center; transform: scaleX(1); }
}

keyframes.ms-hx-bldPop:
@keyframes ms-hx-bldPop { 
  0% { opacity: 0.3; transform: scale(0.9); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-ht-show-c:
@keyframes ms-ht-show-c { 
  0% { opacity: 0; transform: translate(-50%, 9px); }
  100% { opacity: 1; transform: translate(-50%); }
}

keyframes.ms-ht-b-open:
@keyframes ms-ht-b-open { 
  0% { opacity: 0; max-height: 0px; margin-bottom: -10.5px; }
  100% { opacity: 1; max-height: 60px; }
}

keyframes.ms-ht-bd-tabs:
@keyframes ms-ht-bd-tabs { 
  0%, 21% { max-height: 60px; margin-top: var(--space-18); margin-bottom: calc(var(--space-10) * 1.5); opacity: 1; }
  24%, 100% { opacity: 0; max-height: 0px; margin-top: 0px; margin-bottom: 0px; }
}

keyframes.ms-ht-bd-gs:
@keyframes ms-ht-bd-gs { 
  0%, 22%, 51.5%, 100% { border-color: color-mix(in srgb, var(--color-supernova) 32%, var(--color-white)); box-shadow: 0 0 0 4.5px color-mix(in srgb, var(--color-supernova) 8%, transparent); }
  24.5%, 48% { border-color: var(--color-orbit-dark); box-shadow: 0 0 0 4.5px color-mix(in srgb, var(--color-orbit-dark) 14%, transparent); }
}

keyframes.ms-ht-bd-gv:
@keyframes ms-ht-bd-gv { 
  0%, 50% { border-color: color-mix(in srgb, var(--color-supernova) 32%, var(--color-white)); box-shadow: 0 0 0 4.5px color-mix(in srgb, var(--color-supernova) 8%, transparent); }
  52.5%, 100% { border-color: var(--color-orbit-dark); box-shadow: 0 0 0 4.5px color-mix(in srgb, var(--color-orbit-dark) 14%, transparent); }
}

keyframes.ms-ht-sl-on:
@keyframes ms-ht-sl-on { 
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-bmx-comet:
@keyframes ms-bmx-comet { 
  0% { offset-distance: 0%; opacity: 0; }
  1% { opacity: 0.9; }
  7% { offset-distance: 100%; opacity: 0; }
  100% { offset-distance: 100%; opacity: 0; }
}

keyframes.ms-bmx-spk:
@keyframes ms-bmx-spk { 
  0% { opacity: 0; transform: scale(0.3) rotate(0deg); }
  40% { opacity: 1; transform: scale(1.1) rotate(20deg); }
  100% { opacity: 0; transform: scale(0.8) rotate(45deg) translate(6px, -10px); }
}

keyframes.ms-bmx-bmtIn:
@keyframes ms-bmx-bmtIn { 
  0% { opacity: 0; transform: translateY(12px) scale(0.98); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-bmx-wOn:
@keyframes ms-bmx-wOn { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: none; }
}

keyframes.ms-bmx-artIn:
@keyframes ms-bmx-artIn { 
  0% { opacity: 0; transform: translateY(10px) scale(0.97); }
  100% { opacity: 1; transform: none; }
}
